{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        {
          "speaker": "partner",
          "text": "Would you like to dance?"
        },
        {
          "speaker": "you",
          "text": "Sure, I'd love to."
        },
        {
          "speaker": "you",
          "text": "No, thank you.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "We'll go slowly."
        },
        {
          "speaker": "partner",
          "text": "Maybe next song.",
          "or": true
        },
        {
          "speaker": "you",
          "text": "I'm a complete beginner."
        },
        {
          "speaker": "partner",
          "text": "That's okay."
        }
      ],
      "vocab": ["dance", "beginner", "slowly", "song"]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        {
          "speaker": "you",
          "text": "You dance really well."
        },
        {
          "speaker": "partner",
          "text": "Thanks, that's kind of you."
        },
        {
          "speaker": "partner",
          "text": "How long have you been dancing?"
        },
        {
          "speaker": "you",
          "text": "I'm just starting."
        },
        {
          "speaker": "partner",
          "text": "You'll learn quickly."
        },
        {
          "speaker": "you",
          "text": "Thanks."
        }
      ],
      "vocab": ["dance", "well", "start", "learn", "quickly"]
    },
    {
      "title": "Chat between songs",
      "lines": [
        {
          "speaker": "partner",
          "text": "Is this your first time here?"
        },
        {
          "speaker": "you",
          "text": "Yes, it is."
        },
        {
          "speaker": "you",
          "text": "No, I come sometimes.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "Do you live in Austin?"
        },
        {
          "speaker": "you",
          "text": "Yes, I live here."
        },
        {
          "speaker": "you",
          "text": "No, I'm visiting.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "Would you like to dance again?"
        },
        {
          "speaker": "you",
          "text": "Sure, I'd love to."
        },
        {
          "speaker": "you",
          "text": "Maybe later.",
          "or": true
        }
      ],
      "vocab": ["first", "sometimes", "live", "visit", "later"]
    }
  ]
}
